<?php// Check PHP version$requiredPhpVersion = '7.4.0';if (version_compare(PHP_VERSION, $requiredPhpVersion, '<')) {    die("Error: This script requires PHP version $requiredPhpVersion or higher. Current version: " . PHP_VERSION);}// Check if required extensions are installed$requiredExtensions = ['mysqli', 'mbstring', 'zip', 'xml', 'gd'];$missingExtensions = [];foreach ($requiredExtensions as $ext) {    if (!extension_loaded($ext)) {        $missingExtensions[] = $ext;    }}if (!empty($missingExtensions)) {    die("Error: The following required PHP extensions are missing: " . implode(', ', $missingExtensions));}// Check if Composer is installed and required libraries are availableif (!file_exists('vendor/autoload.php')) {    echo "PhpSpreadsheet library not found. Please install dependencies.<br>";    echo "Run these commands in your terminal:<br>";    echo "<pre>    composer require phpoffice/phpspreadsheet    </pre>";    exit();}// Create temp directory for uploads if it doesn't exist$tempDir = 'temp';if (!is_dir($tempDir)) {    if (!mkdir($tempDir, 0755, true)) {        die("Error: Failed to create temporary directory. Please check permissions.");    }    // Create .htaccess file to protect directory    $htaccess = "# Deny access to all files in this directory<FilesMatch \".*\">    Order Allow,Deny    Deny from all</FilesMatch>";    file_put_contents($tempDir . '/.htaccess', $htaccess);}// Output success messageecho "Setup completed successfully!<br>";echo "- PHP version: " . PHP_VERSION . " ✓<br>";echo "- Required extensions: All installed ✓<br>";echo "- Temporary directory created: $tempDir ✓<br>";echo "<p>You can now use the product import/export functionality.</p>";echo "<a href='product_import_export.php' class='btn btn-primary'>Go to Import/Export Page</a>";?>